import{_ as e,a,o as d,a6 as o}from"./chunks/framework.CJDy2q7X.js";const p=JSON.parse('{"title":"Catalog Attribute Family — Detail (GraphQL)","description":"","frontmatter":{"outline":false,"examples":[{"id":"admin-catalog-family-detail","title":"Attribute Family Detail (with attribute groups and attributes)","description":"Fetch a single attribute family by IRI including all attribute groups and — within each group — all associated attributes with pivot position. The attributeGroups field is returned as whole JSON — query it as a bare field; the entire structure resolves over GraphQL.","query":"query AdminAttributeFamily($id: ID!) {\\n  adminAttributeFamily(id: $id) {\\n    id\\n    _id\\n    code\\n    name\\n    attributeGroups\\n  }\\n}\\n","variables":"{\\n  \\"id\\": \\"/api/admin/catalog/families/1\\"\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"adminAttributeFamily\\": {\\n      \\"id\\": \\"/api/admin/catalog/families/1\\",\\n      \\"_id\\": 1,\\n      \\"code\\": \\"default\\",\\n      \\"name\\": \\"Default\\",\\n      \\"attributeGroups\\": [\\n        {\\n          \\"id\\": 1,\\n          \\"code\\": \\"general\\",\\n          \\"name\\": \\"General\\",\\n          \\"column\\": 1,\\n          \\"position\\": 1,\\n          \\"attributes\\": [\\n            {\\n              \\"id\\": 1,\\n              \\"code\\": \\"sku\\",\\n              \\"type\\": \\"text\\",\\n              \\"isRequired\\": 1,\\n              \\"column\\": 1,\\n              \\"position\\": 1\\n            },\\n            {\\n              \\"id\\": 2,\\n              \\"code\\": \\"name\\",\\n              \\"type\\": \\"text\\",\\n              \\"isRequired\\": 1,\\n              \\"column\\": 1,\\n              \\"position\\": 2\\n            }\\n          ]\\n        }\\n      ]\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/catalog/families/families-detail.md","filePath":"api/graphql-api/admin/catalog/families/families-detail.md","lastUpdated":1787290888000}'),i={name:"api/graphql-api/admin/catalog/families/families-detail.md"};function r(n,t,s,c,l,u){return d(),a("div",null,t[0]||(t[0]=[o('<h1 id="catalog-attribute-family-—-detail-graphql" tabindex="-1">Catalog Attribute Family — Detail (GraphQL) <a class="header-anchor" href="#catalog-attribute-family-—-detail-graphql" aria-label="Permalink to &quot;Catalog Attribute Family — Detail (GraphQL)&quot;">​</a></h1><p>GraphQL item query that returns a single attribute family by its IRI, including all <strong>attribute groups</strong> and — within each group — all <strong>attributes</strong> associated via the <code>attribute_group_mappings</code> pivot (with their pivot <code>position</code> and <code>column</code>).</p><p>This is the query to call when an admin needs the complete structure of an attribute family — e.g. when pre-populating the edit form in <strong>Catalog → Attribute Families</strong>.</p><h2 id="operation" tabindex="-1">Operation <a class="header-anchor" href="#operation" aria-label="Permalink to &quot;Operation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Type</th></tr></thead><tbody><tr><td><code>adminAttributeFamily</code></td><td>Query (item)</td></tr></tbody></table><h2 id="arguments" tabindex="-1">Arguments <a class="header-anchor" href="#arguments" aria-label="Permalink to &quot;Arguments&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Argument</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>ID!</code></td><td>Yes</td><td>API Platform IRI of the attribute family (e.g. <code>&quot;/api/admin/catalog/families/1&quot;</code>)</td></tr></tbody></table><p>Take the IRI straight from the <code>id</code> of an <a href="/api/graphql-api/admin/catalog/families/families-listing.html"><code>adminAttributeFamilies</code></a> edge node, or build it as <code>/api/admin/catalog/families/&lt;numericId&gt;</code>.</p><h2 id="fields" tabindex="-1">Fields <a class="header-anchor" href="#fields" aria-label="Permalink to &quot;Fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>ID</code></td><td>API Platform IRI (e.g. <code>/api/admin/catalog/families/1</code>)</td></tr><tr><td><code>_id</code></td><td><code>Int</code></td><td>Raw family ID</td></tr><tr><td><code>code</code></td><td><code>String</code></td><td>Family code (e.g. <code>default</code>, <code>apparel</code>)</td></tr><tr><td><code>name</code></td><td><code>String</code></td><td>Family display name (e.g. <code>Default</code>, <code>Apparel</code>)</td></tr><tr><td><code>attributeGroups</code></td><td>scalar (JSON array|null)</td><td>All attribute groups with nested attributes — see shape below</td></tr></tbody></table><h3 id="attributegroups-item-shape" tabindex="-1"><code>attributeGroups</code> item shape <a class="header-anchor" href="#attributegroups-item-shape" aria-label="Permalink to &quot;`attributeGroups` item shape&quot;">​</a></h3><p><code>attributeGroups</code> is returned as a <strong>plain JSON array</strong> (scalar in GraphQL). Each element corresponds to one row in <code>attribute_groups</code>:</p><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Attribute group ID</td></tr><tr><td><code>code</code></td><td>string</td><td>Group code (e.g. <code>general</code>, <code>price</code>)</td></tr><tr><td><code>name</code></td><td>string</td><td>Group display name</td></tr><tr><td><code>column</code></td><td>integer</td><td>Layout column position for the group</td></tr><tr><td><code>position</code></td><td>integer</td><td>Display order position of the group within the family</td></tr><tr><td><code>attributes</code></td><td>array</td><td>Attributes mapped to this group (see below)</td></tr></tbody></table><h3 id="attributegroups-attributes-item-shape" tabindex="-1"><code>attributeGroups[].attributes[]</code> item shape <a class="header-anchor" href="#attributegroups-attributes-item-shape" aria-label="Permalink to &quot;`attributeGroups[].attributes[]` item shape&quot;">​</a></h3><p>Each element corresponds to one attribute mapped via <code>attribute_group_mappings</code>:</p><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Attribute ID</td></tr><tr><td><code>code</code></td><td>string</td><td>Attribute code (e.g. <code>sku</code>, <code>name</code>, <code>color</code>)</td></tr><tr><td><code>type</code></td><td>string</td><td>Attribute type (e.g. <code>text</code>, <code>select</code>, <code>boolean</code>)</td></tr><tr><td><code>isRequired</code></td><td>integer</td><td><code>1</code> = required on product forms, <code>0</code> = optional</td></tr><tr><td><code>column</code></td><td>integer</td><td>Layout column position of this attribute within the group</td></tr><tr><td><code>position</code></td><td>integer</td><td>Display order position of this attribute within the group</td></tr></tbody></table><h3 id="attributegroups-is-a-json-scalar" tabindex="-1">attributeGroups Is a JSON Scalar <a class="header-anchor" href="#attributegroups-is-a-json-scalar" aria-label="Permalink to &quot;attributeGroups Is a JSON Scalar&quot;">​</a></h3><p>Select <code>attributeGroups</code> as a <strong>bare field</strong> — a sub-selection is a schema error. The whole structure comes back in one piece, each group carrying its own nested <code>attributes</code> list.</p><p>Every id inside is numeric, not an IRI: a group&#39;s <code>id</code>, and each attribute&#39;s <code>id</code>. Use those directly when referencing an attribute elsewhere.</p><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scenario</th><th>GraphQL <code>errors[]</code></th><th>HTTP Status</th></tr></thead><tbody><tr><td>Unknown ID</td><td><code>errors[]</code> populated or <code>data.adminAttributeFamily: null</code></td><td><code>200</code> (GraphQL convention)</td></tr><tr><td>Missing auth</td><td><code>&quot;Unauthenticated&quot;</code> in <code>errors[]</code></td><td><code>200</code></td></tr></tbody></table><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li><strong><code>attributeGroups</code> is a plain JSON scalar</strong>, not a typed GraphQL object list. You access it as a regular JSON array in the response. This avoids API Platform serializing nested objects as IRI strings instead of inline objects — a known behavior when using nested DTO types in API Platform GraphQL.</li><li><strong><code>attributeGroups</code> is returned whole</strong> — query it as a bare field (not with a sub-selection); the entire structure resolves over GraphQL. The REST detail endpoint returns the same array.</li><li><strong>GraphQL and REST return identical data</strong> for this query — both embed every group with its nested attributes including the <code>column</code> and <code>position</code> fields.</li><li><strong>The <code>id</code> argument is the IRI</strong>, not the numeric integer. Construct it as <code>&quot;/api/admin/catalog/families/{_id}&quot;</code> using the <code>_id</code> field from a listing query, or pass the <code>id</code> field directly from a listing result.</li><li><strong>No timestamps.</strong> The <code>attribute_families</code> table has <code>$timestamps = false</code>, so <code>createdAt</code> and <code>updatedAt</code> are not available on either transport.</li><li><strong>Attribute detail fields are slim.</strong> Each attribute inside <code>attributeGroups[].attributes</code> carries only the fields needed for family-structure display: <code>id</code>, <code>code</code>, <code>type</code>, <code>isRequired</code>, <code>column</code>, <code>position</code>. For the full attribute payload (translations, options, validation), use <code>adminAttribute(id: ID!)</code> or <code>GET /api/admin/catalog/attributes/{id}</code>.</li></ul>',23)]))}const b=e(i,[["render",r]]);export{p as __pageData,b as default};
